    if(head){if(heading)fail('SOURCE_PARSE_FAILED',`${path}:${heading.line} missing law record`);if(!head[1])fail('SOURCE_PARSE_FAILED',`${path}:${i+1} law heading`);heading={lawId:head[1]!,line:i+1};continue}
    if(line!=='```law-record'){if(line.startsWith('```')||/^\s+```/u.test(line))fail('SOURCE_PARSE_FAILED',`${path}:${i+1} orphan or nested fence`);continue}
    if(!heading||!domain) fail('SOURCE_PARSE_FAILED',`${path}:${i+1}`); const currentHeading=heading as {lawId:string;line:number}; const start=i+1; let end=i+1;
