function projectChecks(level:Level,laws:Law[],runDirectory:string):CheckResult[]{
  const pkg=parseJson<Record<string,any>>('package.json'); const pm=existsSync(resolve(ROOT,'pnpm-lock.yaml'))?'pnpm':'npm'; const definitions=new Map<string,{domains:Set<string>;modes:Set<string>}>();
  const add=(script:string,domains:string[],modes:string[])=>{const current=definitions.get(script)??{domains:new Set<string>(),modes:new Set<string>()};domains.forEach((domain)=>current.domains.add(domain));modes.forEach((mode)=>current.modes.add(mode));definitions.set(script,current)};
  const staticModes=(domain:string)=>orderedModes(laws.filter((law)=>law.capabilityDomain===domain).flatMap((law)=>law.evidenceModes.filter((mode)=>mode!=='static.ast'&&mode!=='static.types'&&!mode.startsWith('dynamic.'))));
  if(level!=='CHANGE'){
    add('audit:integrity:test',['project-governance'],staticModes('project-governance'));
    add('typecheck',['*'],['static.ast','static.types']);
    for(const [domain,scripts] of Object.entries(DOMAIN_READY_SCRIPTS))for(const script of scripts)add(script,[domain],staticModes(domain));
  }else add('audit:integrity:test',['project-governance'],['static.filesystem','static.text','static.contract','static.dependency','static.config','static.json']);
  const results:CheckResult[]=[];
  for(const [script,definition] of [...definitions.entries()].sort(([left],[right])=>left.localeCompare(right))){const domains=[...definition.domains].sort();const modes=[...definition.modes];if(typeof pkg.scripts?.[script]!=='string'){const receiptPath=resolve(runDirectory,`${script.replace(/[^a-zA-Z0-9_.-]/gu,'_')}.result.json`);const receipt={schemaVersion:1,testId:`script:${script}`,lawIds:laws.filter((law)=>domains.includes('*')||domains.includes(law.capabilityDomain)).map((law)=>law.lawId).sort(),evidenceModes:orderedModes(modes),command:`${pm} run ${script}`,outcome:'FAIL',finding:'PROJECT_CHECK_MISSING'};const receiptHash=writeEvidence(receiptPath,receipt as unknown as Json);results.push({checkId:`script:${script}`,domains,lawIds:receipt.lawIds,evidenceModes:orderedModes(modes),command:`${pm} run ${script}`,outcome:'FAIL',evidenceRef:`${receiptPath}#sha256=${receiptHash}`,finding:'PROJECT_CHECK_MISSING'});continue}results.push(runCheck(pm,script,domains,modes,laws,runDirectory))}
  return results;
}
function lawIntersects(law:Pick<Law,'appliesTo'|'excludes'|'contractRefs'>,diffs:string[]){const included=diffs.some((path)=>law.appliesTo.some((pattern)=>matchPath(pattern,path))&&!law.excludes.some((pattern)=>matchPath(pattern,path)));return included||law.contractRefs.some((ref)=>diffs.includes(ref.path))}
export function evidencePlan(law:Pick<Law,'appliesTo'|'excludes'|'contractRefs'|'evidenceModes'>,diffs:string[],level:'READY'|'RELEASE'){if(!lawIntersects(law,diffs))return{applicableEvidenceModes:[] as string[],deferredEvidenceModes:[] as string[]};const staticAndExam=orderedModes(law.evidenceModes.filter((mode)=>!mode.startsWith('dynamic.')));const dynamic=orderedModes(law.evidenceModes.filter((mode)=>mode.startsWith('dynamic.')));return{applicableEvidenceModes:level==='RELEASE'?[...staticAndExam,...dynamic]:staticAndExam,deferredEvidenceModes:level==='READY'?dynamic:[]}}
function candidateSnapshot(){const commit=execFileSync('git',['rev-parse','HEAD'],{cwd:ROOT}).toString().trim();const diff=execFileSync('git',['diff','--binary','--no-ext-diff','HEAD','--'],{cwd:ROOT});const untracked=execFileSync('git',['ls-files','--others','--exclude-standard','-z'],{cwd:ROOT}).toString().split('\0').filter(Boolean).sort();const identity={commit,diffSha256:sha(diff),untracked:untracked.map((path)=>({path:norm(path),sha256:sha(bytes(path))}))};return sha(canonicalBytes(identity as unknown as Json))}
type ReleaseBinding={candidateId:string;gitCommit:string;freezeSha256:string;baseLawSha256:string;functionalLawSha256:string;registrySha256:string};
export function releaseCandidateBinding():ReleaseBinding{const dirty=execFileSync('git',['status','--porcelain=v1','-z','--untracked-files=all'],{cwd:ROOT});if(dirty.length)fail('RELEASE_CANDIDATE_UNBOUND','RELEASE requires a clean committed tree');const gitCommit=execFileSync('git',['rev-parse','HEAD'],{cwd:ROOT}).toString().trim();const baseLawSha256=sha(bytes(BASE));const functionalLawSha256=sha(bytes(FUNCTIONAL));const registrySha256=sha(bytes(REGISTRY));const candidateId=sha(canonicalBytes({gitCommit,baseLawSha256,functionalLawSha256,registrySha256}));return{candidateId,gitCommit,freezeSha256:sha(bytes(FREEZE)),baseLawSha256,functionalLawSha256,registrySha256}}
type ProofFileIdentity={dev:number;ino:number;size:number;mtimeMs:number};
type VerifiedDynamicProof={lawIds:string[];evidenceModes:string[];evidenceRefs:string[];dynamicProofEvidenceRefs:string[];hashes:string[]};
type ProofRunner=(script:string,args:string[],env:NodeJS.ProcessEnv)=>{status:number|null;stdout:string;stderr:string};
const realProofRunner:ProofRunner=(script,args,env)=>{const result=spawnSync(process.execPath,['--import','tsx',script,...args],{cwd:ROOT,encoding:'utf8',env,maxBuffer:16*1024*1024});return{status:result.status,stdout:result.stdout??'',stderr:result.stderr??''}};
export function verifyXuanxueReleaseEvidence(evidencePath:string,runner:ProofRunner=realProofRunner):VerifiedDynamicProof{
  const absolute=resolve(evidencePath);
  const runRoot=resolve(ROOT,'.grasseye-local');
  const bindingPath=resolve(runRoot,'xuanxue-ai-production-dynamic-proof-binding.v2.json');
  let evidenceRaw:Buffer;let bindingRaw:Buffer;let evidence:any;let binding:any;let evidenceIdentity:ProofFileIdentity;let bindingIdentity:ProofFileIdentity;
  try{const evidenceStat=lstatSync(absolute);const bindingStat=lstatSync(bindingPath);evidenceIdentity={dev:evidenceStat.dev,ino:evidenceStat.ino,size:evidenceStat.size,mtimeMs:evidenceStat.mtimeMs};bindingIdentity={dev:bindingStat.dev,ino:bindingStat.ino,size:bindingStat.size,mtimeMs:bindingStat.mtimeMs};evidenceRaw=readFileSync(absolute);bindingRaw=readFileSync(bindingPath);evidence=JSON.parse(utf8.decode(evidenceRaw));binding=JSON.parse(utf8.decode(bindingRaw))}catch(error){return fail('RELEASE_EVIDENCE_MISSING',`invalid real proof authority: ${error instanceof Error?error.message:String(error)}`)}
  if(!evidence||!exactKeys(evidence,['schemaVersion','contractManifestHash','extensionId','releaseMode','workbenchUrl','realRunRoot','dynamicProofRunId','runtimeReceipt','evidenceRefs'])||evidenceRaw!.toString('utf8')!==canonicalBytes(evidence as Json))fail('RELEASE_EVIDENCE_MISSING','real Chrome evidence must be exact canonical V6 evidence');
  if(!binding||binding.schema_version!=='xuanxue-ai-production-dynamic-proof-binding.v2'||evidence.dynamicProofRunId!==binding.run_id)fail('RELEASE_EVIDENCE_MISSING','real Chrome evidence is not bound to the production proof run');
  const commands=[
    {script:'scripts/acceptance/xuanxue-ai-production.real-chrome.ts',args:['--evidence',absolute],env:{...process.env},marker:'"status":"CHROME_VERIFIED"'},
    {script:'scripts/acceptance/xuanxue-ai-production.real-provider.ts',args:['--evidence',absolute],env:{...process.env,XUANXUE_AI_REAL_RUN_ROOT:runRoot},marker:'"status": "PASS"'},
  ];
  const results=commands.map((command)=>{const result=runner(command.script,command.args,command.env);if(result.status!==0||!result.stdout.includes(command.marker))fail('RELEASE_EVIDENCE_MISSING',`real proof executor failed: ${command.script}: ${result.stderr||result.stdout}`);return result});
  let chromeResult:any;let providerResult:any;try{chromeResult=JSON.parse(results[0]!.stdout);providerResult=JSON.parse(results[1]!.stdout)}catch{fail('RELEASE_EVIDENCE_MISSING','real proof executor output is not exact JSON')}
  if(chromeResult.contractManifestHash!==evidence.contractManifestHash||chromeResult.workerSessionId!==evidence.runtimeReceipt?.worker_session_id||chromeResult.runtimeAttestationReceiptHash!==evidence.runtimeReceipt?.runtime_attestation_receipt_hash||providerResult.runId!==binding.run_id||providerResult.candidateHash!==binding.candidate_hash||providerResult.contractManifestHash!==binding.contract_manifest_hash)fail('RELEASE_EVIDENCE_MISSING','real proof executor output does not match the bound artifacts');
  assertStableProofFile(absolute,evidenceRaw!,evidenceIdentity!);assertStableProofFile(bindingPath,bindingRaw!,bindingIdentity!);
  const bindingHash=sha(bindingRaw!);const evidenceHash=sha(evidenceRaw!);
  const artifacts=[{evidenceRef:`${absolute}#sha256=${evidenceHash}`,hash:evidenceHash},{evidenceRef:`${bindingPath}#sha256=${bindingHash}`,hash:bindingHash}].sort((left,right)=>left.evidenceRef.localeCompare(right.evidenceRef));
  return{lawIds:['LAW-XUANXUE-AI-PRODUCTION-001-V6'],evidenceModes:['dynamic.browser','dynamic.service','dynamic.provider','dynamic.authorization'],evidenceRefs:artifacts.map((artifact)=>artifact.evidenceRef),dynamicProofEvidenceRefs:artifacts.map((artifact)=>artifact.evidenceRef),hashes:artifacts.map((artifact)=>artifact.hash)};
}
export function assertStableProofFile(path:string,before:Buffer,identity:ProofFileIdentity):void{let after:Buffer;let stat:ReturnType<typeof lstatSync>;try{stat=lstatSync(path);after=readFileSync(path)}catch{return fail('RELEASE_EVIDENCE_MISSING','real proof artifact disappeared during verification')}if(stat.dev!==identity.dev||stat.ino!==identity.ino||stat.size!==identity.size||stat.mtimeMs!==identity.mtimeMs||!after.equals(before))fail('CANDIDATE_DRIFT','real proof artifact changed during verification')}
function releaseDynamicProofs(){const legacy=process.env.GRASSEYE_RELEASE_DYNAMIC_PROOF_PATHS;if(legacy!==undefined)fail('RELEASE_EVIDENCE_MISSING','caller-authored Dynamic Proof wrappers are retired');const evidencePath=process.env.GRASSEYE_RELEASE_XUANXUE_REAL_CHROME_EVIDENCE?.trim();return evidencePath?[verifyXuanxueReleaseEvidence(evidencePath)]:[]}
type ReleaseParticipant={contractId:string;contractVersion:number;repo:string;releaseSha256:string};
export function validateReleaseProofPackage(value:any):void{if(!value||!exactKeys(value,['schemaVersion','candidateId','gitCommit','freezeSha256','baseLawSha256','functionalLawSha256','registrySha256','lawQualityReportSha256','dynamicProofHashes','crossRepoParticipants'])||value.schemaVersion!==1||typeof value.candidateId!=='string'||!/^[a-f0-9]{64}$/u.test(value.candidateId)||typeof value.gitCommit!=='string'||!/^[a-f0-9]{40}$/u.test(value.gitCommit))fail('RELEASE_EVIDENCE_MISSING','invalid RELEASE proof package');for(const field of ['freezeSha256','baseLawSha256','functionalLawSha256','registrySha256','lawQualityReportSha256'])if(typeof value[field]!=='string'||!/^[a-f0-9]{64}$/u.test(value[field]))fail('RELEASE_EVIDENCE_MISSING',`invalid RELEASE package ${field}`);if(!isStringArray(value.dynamicProofHashes)||!sortedUnique(value.dynamicProofHashes)||value.dynamicProofHashes.some((hash:string)=>!/^[a-f0-9]{64}$/u.test(hash))||!Array.isArray(value.crossRepoParticipants))fail('RELEASE_EVIDENCE_MISSING','invalid RELEASE package evidence');let prior='';for(const participant of value.crossRepoParticipants){const repo=typeof participant?.repo==='string'?repositoryIdentity(participant.repo):'';if(!participant||!exactKeys(participant,['contractId','contractVersion','repo','releaseSha256'])||!cleanString(participant.contractId)||!Number.isInteger(participant.contractVersion)||participant.contractVersion<1||repo.split('/').length!==2||!/^[a-f0-9]{64}$/u.test(participant.releaseSha256))fail('RELEASE_EVIDENCE_MISSING','invalid RELEASE participant');const key=canonicalBytes([participant.contractId,participant.contractVersion,repo] as unknown as Json);if(key<=prior)fail('RELEASE_EVIDENCE_MISSING','unsorted RELEASE participants');prior=key}}
export function agentReleaseParticipants(requested=process.env.GRASSEYE_RELEASE_CROSS_REPO_PARTICIPANTS):ReleaseParticipant[]{if(requested!==undefined)fail('RELEASE_EVIDENCE_MISSING','AGENT RELEASE is the upstream participant leaf; cross-repo participants are forbidden');return[]}
export function validateQualityReport(report:any,laws:Pick<Law,'lawId'>[],level:'READY'|'RELEASE'){if(!report||!exactKeys(report,['schemaVersion','level','baseSha','candidateId','registrySha256','laws','outcome'])||report.schemaVersion!==1||report.level!==level||typeof report.baseSha!=='string'||!/^[a-f0-9]{40}$/u.test(report.baseSha)||typeof report.registrySha256!=='string'||!/^[a-f0-9]{64}$/u.test(report.registrySha256)||!['PASS','FAIL'].includes(report.outcome))fail('QUALITY_REPORT_INVALID','top-level');if(level==='READY'&&report.candidateId!==null)fail('QUALITY_REPORT_INVALID','READY candidateId');if(level==='RELEASE'&&(typeof report.candidateId!=='string'||!/^[a-f0-9]{64}$/u.test(report.candidateId)))fail('QUALITY_REPORT_INVALID','RELEASE candidateId');if(!Array.isArray(report.laws)||report.laws.length!==laws.length)fail('QUALITY_REPORT_INVALID','law denominator');for(let index=0;index<laws.length;index++){const item=report.laws[index];const evidenceRequired=Boolean(item?.applicableEvidenceModes?.length||item?.deferredEvidenceModes?.length);if(!item||!exactKeys(item,['lawId','applicableEvidenceModes','deferredEvidenceModes','outcome','evidenceRefs','findings'])||item.lawId!==laws[index]!.lawId||!isStringArray(item.applicableEvidenceModes)||!isStringArray(item.deferredEvidenceModes)||JSON.stringify(item.applicableEvidenceModes)!==JSON.stringify(orderedModes(item.applicableEvidenceModes))||JSON.stringify(item.deferredEvidenceModes)!==JSON.stringify(orderedModes(item.deferredEvidenceModes))||!['PASS','FAIL'].includes(item.outcome)||!isStringArray(item.evidenceRefs)||!sortedUnique(item.evidenceRefs)||item.evidenceRefs.some((reference:string)=>!cleanString(reference))||!isStringArray(item.findings)||!sortedUnique(item.findings)||item.findings.some((finding:string)=>!/^[A-Z][A-Z0-9_]*$/u.test(finding))||(item.outcome==='PASS'&&((evidenceRequired&&!item.evidenceRefs.length)||item.findings.length))||(item.outcome==='FAIL'&&!item.findings.length)||(level==='RELEASE'&&item.deferredEvidenceModes.length))fail('QUALITY_REPORT_INVALID',`law ${item?.lawId??index}`)}const expected=report.laws.some((item:any)=>item.outcome==='FAIL')?'FAIL':'PASS';if(report.outcome!==expected)fail('QUALITY_REPORT_INVALID','aggregate outcome')}
function writeReport(laws:Law[],baseSha:string,checks:CheckResult[],diffs:string[],runDirectory:string){const registrySha=sha(bytes(REGISTRY));const items=laws.map((law)=>{const {applicableEvidenceModes:applicable,deferredEvidenceModes:deferred}=evidencePlan(law,diffs,'READY');const relevant=(applicable.length||deferred.length)?checks.filter((check)=>check.domains.includes('*')||check.domains.includes(law.capabilityDomain)):[];const covered=new Set(relevant.filter((check)=>check.outcome==='PASS').flatMap((check)=>check.evidenceModes));const missing=applicable.filter((mode)=>!covered.has(mode));const failed=relevant.filter((check)=>check.outcome==='FAIL');const findings=[...new Set([...missing.map((mode)=>`REQUIRED_EVIDENCE_MODE_UNPROVEN_${mode.replace(/[^A-Za-z0-9]/gu,'_').toUpperCase()}`),...failed.map((check)=>check.finding!).filter(Boolean)])].sort();const evidenceRefs=relevant.filter((check)=>check.outcome==='PASS').map((check)=>check.evidenceRef).sort().filter((value,index,array)=>index===0||value!==array[index-1]);return{lawId:law.lawId,applicableEvidenceModes:applicable,deferredEvidenceModes:deferred,outcome:findings.length?'FAIL':'PASS',evidenceRefs,findings}});const report={schemaVersion:1,level:'READY' as const,baseSha,candidateId:null,registrySha256:registrySha,laws:items,outcome:items.some((item)=>item.outcome==='FAIL')?'FAIL':'PASS'};validateQualityReport(report,laws,'READY');const reportPath=process.env.GRASSEYE_QUALITY_REPORT_MODE==='external'?resolve(runDirectory,'law-quality.report.json'):resolve(ROOT,REPORT);mkdirSync(dirname(reportPath),{recursive:true});writeFileSync(reportPath,canonicalBytes(report as unknown as Json),{mode:0o600});return{outcome:report.outcome,path:reportPath,hash:sha(readFileSync(reportPath))}}
function writeReleaseReport(laws:Law[],baseSha:string,binding:ReleaseBinding,checks:CheckResult[],diffs:string[],proofs:ReturnType<typeof releaseDynamicProofs>,runDirectory:string){const referencedDynamicProofHashes=new Set<string>();const items=laws.map((law)=>{const {applicableEvidenceModes:applicable}=evidencePlan(law,diffs,'RELEASE');const staticChecks=checks.filter((check)=>check.domains.includes('*')||check.domains.includes(law.capabilityDomain));const lawProofs=proofs.filter((proof)=>proof.lawIds.includes(law.lawId));const covered=new Set([...staticChecks.filter((check)=>check.outcome==='PASS').flatMap((check)=>check.evidenceModes),...lawProofs.flatMap((proof)=>proof.evidenceModes)]);const missing=applicable.filter((mode)=>!covered.has(mode));const failed=staticChecks.filter((check)=>check.outcome==='FAIL');const findings=[...new Set([...missing.map((mode)=>`REQUIRED_EVIDENCE_MODE_UNPROVEN_${mode.replace(/[^A-Za-z0-9]/gu,'_').toUpperCase()}`),...failed.map((check)=>check.finding!).filter(Boolean)])].sort();const evidenceRefs=[...staticChecks.filter((check)=>check.outcome==='PASS').map((check)=>check.evidenceRef),...lawProofs.flatMap((proof)=>proof.evidenceRefs)].sort().filter((value,index,array)=>index===0||value!==array[index-1]);for(const proof of lawProofs)for(let index=0;index<proof.dynamicProofEvidenceRefs.length;index++)if(evidenceRefs.includes(proof.dynamicProofEvidenceRefs[index]!))referencedDynamicProofHashes.add(proof.hashes[index]!);return{lawId:law.lawId,applicableEvidenceModes:applicable,deferredEvidenceModes:[] as string[],outcome:findings.length?'FAIL':'PASS',evidenceRefs,findings}});const report={schemaVersion:1,level:'RELEASE' as const,baseSha,candidateId:binding.candidateId,registrySha256:binding.registrySha256,laws:items,outcome:items.some((item)=>item.outcome==='FAIL')?'FAIL':'PASS'};validateQualityReport(report,laws,'RELEASE');const reportPath=process.env.GRASSEYE_QUALITY_REPORT_MODE==='external'?resolve(runDirectory,'law-quality.report.json'):resolve(ROOT,REPORT);mkdirSync(dirname(reportPath),{recursive:true});writeFileSync(reportPath,canonicalBytes(report as unknown as Json),{mode:0o600});return{outcome:report.outcome,path:reportPath,hash:sha(readFileSync(reportPath)),dynamicProofHashes:[...referencedDynamicProofHashes].sort()}}
function writeReleasePackage(binding:ReleaseBinding,reportHash:string,dynamicProofHashes:string[]){const proofPackage={schemaVersion:1,candidateId:binding.candidateId,gitCommit:binding.gitCommit,freezeSha256:binding.freezeSha256,baseLawSha256:binding.baseLawSha256,functionalLawSha256:binding.functionalLawSha256,registrySha256:binding.registrySha256,lawQualityReportSha256:reportHash,dynamicProofHashes,crossRepoParticipants:agentReleaseParticipants()};validateReleaseProofPackage(proofPackage);const directory=resolve(ROOT,'.governance/runtime/releases',binding.candidateId);mkdirSync(directory,{recursive:true});const destination=resolve(directory,'proof-package.json');const temporary=`${destination}.tmp-${process.pid}`;writeFileSync(temporary,canonicalBytes(proofPackage as unknown as Json),{mode:0o600});renameSync(temporary,destination);return destination}
function quality(level:Level){if(!['CHANGE','READY','RELEASE'].includes(level))fail('ENTRY_CONTRACT_MISMATCH',`invalid level ${level}`);verifyEntry();const initialCandidate=candidateSnapshot();const diffs=scopeCheck(level==='CHANGE'?'CHANGE':'FULL');const laws=level==='CHANGE'?registeredLaws():buildRegistry().laws;const releaseBinding=level==='RELEASE'?releaseCandidateBinding():null;const runDirectory=qualityRunDirectory();const checks=projectChecks(level,laws,runDirectory);if(candidateSnapshot()!==initialCandidate)fail('CANDIDATE_DRIFT','candidate changed while checks ran');if(level==='READY'){const record=changeRecord();const report=writeReport(laws,record.baseSha,checks,diffs.map((item)=>item.path),runDirectory);if(candidateSnapshot()!==initialCandidate)fail('CANDIDATE_DRIFT','candidate changed before READY verdict');if(report.outcome!=='PASS')fail('QUALITY_FINDINGS_PRESENT',report.path);console.log(`READY_REPORT ${report.path}`)}else if(level==='RELEASE'){const proofs=releaseDynamicProofs();const record=changeRecord();const report=writeReleaseReport(laws,record.baseSha,releaseBinding!,checks,diffs.map((item)=>item.path),proofs,runDirectory);if(candidateSnapshot()!==initialCandidate||releaseCandidateBinding().candidateId!==releaseBinding!.candidateId)fail('CANDIDATE_DRIFT','candidate changed before RELEASE package');if(report.outcome!=='PASS')fail('RELEASE_EVIDENCE_MISSING',report.path);const packagePath=writeReleasePackage(releaseBinding!,report.hash,report.dynamicProofHashes);if(candidateSnapshot()!==initialCandidate||releaseCandidateBinding().candidateId!==releaseBinding!.candidateId)fail('CANDIDATE_DRIFT','candidate changed after RELEASE package');console.log(`RELEASE_PACKAGE ${packagePath}`)}else{const failed=checks.find((check)=>check.outcome==='FAIL');if(failed)fail('PROJECT_CHECK_FAILED',failed.finding??failed.command)}console.log(`${level}_PASS`)}
function main(){const [command,arg]=process.argv.slice(2);if(command==='entry'){verifyEntry();if(arg!=='READ_ONLY'){const record=changeRecord();dirtyTargetCheck(record)}console.log('ENTRY_OK');return}if(command==='scope'){scopeCheck();return}if(command==='build'){writeRegistry();return}if(command==='projection'){checkProjection();return}if(command==='quality'){quality((arg??'CHANGE') as Level);return}fail('ENTRY_CONTRACT_MISMATCH','unknown command')}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){try{main()}catch(error){const e=error as Error;console.error(`${e instanceof GovernanceError?e.code:'GOVERNANCE_INTERNAL_ERROR'} ${e.message}`);process.exitCode=1}}
